@dataclass
class Options:
    n: str = "2"
    top: int = 50
    combi: int = 2
    rep: int = 3
    wpm: int = 40
    acc: int = 94
    emu_in: str = ""
    emu_out: str = ""
    show_ortho: bool = False
    nokb: bool = False
    cat: bool = False


@dataclass
class Lesson:
    visible: str
    expected: str


@dataclass
class GameState:
    options: Options
    pool: list[str]
    output_layout: list[str]
    input_layout: list[str]
    lesson_count: int = 0
    success_count: int = 0
    failure_count: int = 0
    lessons_done: int = 0
    last_wpm: int = 0
    last_acc: int = 0
    avg_wpm: int = 0
    avg_acc: int = 0
    wpm_history: list[int] = field(default_factory=list)
    acc_history: list[int] = field(default_factory=list)
    lesson: Lesson | None = None
    cursor: int = 0
    mistakes: dict[int, list[str]] = field(default_factory=dict)
    typed_actual: dict[int, str] = field(default_factory=dict)
    total_presses: int = 0
    good_presses: int = 0
    started_at: float | None = None
    quitting: bool = False

    def reset_for_next_lesson(self) -> None:
        self.lesson = build_lesson(self.pool, self.options.combi, self.options.rep)
        self.lesson_count += 1
        self.cursor = 0
        self.mistakes = {}
        self.typed_actual = {}
        self.total_presses = 0
        self.good_presses = 0
        self.started_at = None


class TerminalUI:
    def __init__(self) -> None:
        self.fd = sys.stdin.fileno()
        self.old_attrs = None
        self.alt_entered = False

    def enter(self) -> None:
        self.old_attrs = termios.tcgetattr(self.fd)
        tty.setraw(self.fd)
        sys.stdout.write("\x1b[?1049h\x1b[2J\x1b[?25l")
        sys.stdout.flush()
        self.alt_entered = True

    def leave(self) -> None:
        if self.old_attrs is not None:
            termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old_attrs)
        if self.alt_entered:
            sys.stdout.write("\x1b[?25h\x1b[?1049l")
            sys.stdout.flush()
            self.alt_entered = False


def print_help() -> None:
    sys.stdout.write(HELP_TEXT)


def parser_unexpected(arg: str) -> None:
    sys.stderr.write(
        f"error: unexpected argument '{arg}' found\n\n"
        "Usage: executable [OPTIONS]\n\n"
        "For more information, try '--help'.\n"
    )
    raise SystemExit(2)


def parser_missing_value(flag: str) -> None:
    spec = ARG_SPECS[flag]
    sys.stderr.write(
        f"error: a value is required for '{spec}' but none was supplied\n\n"
        "For more information, try '--help'.\n"
    )
    raise SystemExit(2)


def parser_invalid_int(flag: str, value: str) -> None:
    spec = INT_VALUE_ERRORS[flag]
    sys.stderr.write(
        f"error: invalid value '{value}' for '{spec}': invalid digit found in string\n\n"
        "For more information, try '--help'.\n"
    )
    raise SystemExit(2)


def take_value(argv: list[str], index: int) -> tuple[str, int]:
    if index + 1 >= len(argv) or argv[index + 1].startswith("-"):
        parser_missing_value(argv[index])
    return argv[index + 1], index + 2


def parse_int_arg(flag: str, value: str) -> int:
    if not value.isdigit():
        parser_invalid_int(flag, value)
    return int(value)


def parse_args(argv: list[str]) -> Options:
    opts = Options()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ("-h", "--help"):
            print_help()
            raise SystemExit(0)
        if arg in ("-n", "--n"):
            value, i = take_value(argv, i)
            opts.n = value
            continue
        if arg in ("-t", "--top"):
            value, i = take_value(argv, i)
            opts.top = parse_int_arg(arg, value)
            continue
        if arg in ("-c", "--combi"):
            value, i = take_value(argv, i)
            opts.combi = parse_int_arg(arg, value)
            continue
        if arg in ("-r", "--rep"):
            value, i = take_value(argv, i)
            opts.rep = parse_int_arg(arg, value)
            continue
        if arg in ("-w", "--wpm"):
            value, i = take_value(argv, i)
            opts.wpm = parse_int_arg(arg, value)
            continue
        if arg in ("-a", "--acc"):
            value, i = take_value(argv, i)
            opts.acc = parse_int_arg(arg, value)
            continue
        if arg == "--emu-in":
            value, i = take_value(argv, i)
            opts.emu_in = value
            continue
        if arg == "--emu-out":
            value, i = take_value(argv, i)
            opts.emu_out = value
            continue
        if arg == "--show-ortho":
            opts.show_ortho = True
            i += 1
            continue
        if arg == "--nokb":
            opts.nokb = True
            i += 1
            continue
        if arg == "--cat":
            opts.cat = True
            i += 1
            continue
        parser_unexpected(arg)
    return opts


def validate_options(opts: Options) -> None:
    if not 1 <= opts.top <= 200:
        sys.stdout.write("Invalid argument for top. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.combi <= 200:
        sys.stdout.write("Invalid argument for combi. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.rep <= 200:
        sys.stdout.write("Invalid argument for rep. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 1 <= opts.wpm <= 200:
        sys.stdout.write("Invalid argument for wpm. Use a number between 1 and 200.\n")
        raise SystemExit(1)
    if not 0 <= opts.acc <= 100:
        sys.stdout.write("Invalid argument for acc. Use a number between 0 and 100.\n")
        raise SystemExit(1)
    if bool(opts.emu_in) != bool(opts.emu_out):
        sys.stdout.write("You need to specify both emu_in and emu_out.\n")
        raise SystemExit(1)
    if opts.n not in {"2", "3", "4", "w"} and not os.path.exists(opts.n):
        sys.stdout.write(f"File not found: {opts.n}\n")
        raise SystemExit(1)


def load_custom_words(path: str) -> list[str]:
    content = open(path, "r", encoding="utf-8").read()
    if "," in content:
        return [token.rstrip("\r\n") for token in content.split(",") if token.rstrip("\r\n") != ""]
    return content.split()


def get_pool(opts: Options) -> list[str]:
    if opts.n == "2":
        return BIGRAMS[:]
    if opts.n == "3":
        return TRIGRAMS[:]
    if opts.n == "4":
        return TETRAGRAMS[:]
    if opts.n == "w":
        return WORDS[:]
    return load_custom_words(opts.n)


def get_layout_rows(name: str) -> list[str]:
    return LAYOUTS.get(name.lower(), LAYOUTS["qwerty"])["display"]


def build_translation(input_rows: list[str], output_rows: list[str]) -> dict[str, str]:
    mapping: dict[str, str] = {}
    for in_row, out_row in zip(input_rows, output_rows):
        for index, ch in enumerate(in_row):
            if index < len(out_row):
                mapping[ch] = out_row[index]
    return mapping


def build_lesson(pool: list[str], combi: int, rep: int) -> Lesson:
    if not pool:
        return Lesson("", "")
    selected = [random.choice(pool) for _ in range(combi)]
    expected = "".join(f"{token} " for _ in range(rep) for token in selected)
    return Lesson(expected.rstrip(" "), expected)


def center_text(text: str, width: int) -> str:
    if len(text) >= width:
        return text[:width]
    pad = (width - len(text)) // 2
    return " " * pad + text + " " * (width - len(text) - pad)


def blank_line() -> str:
    return "│" + " " * 77 + "│"


def separator_line() -> str:
    return "│" + "─" * 77 + "│"


def border_top() -> str:
    return "╭" + "─" * 65 + " Quit <esc> " + "╮"


def border_bottom() -> str:
    return "╰" + "─" * 77 + "╯"


def metric_line(label: str, need: int, avg: int, last: int) -> str:
    if label == "WPM":
        body = f"  need >= {need:>3}WPM,   avg. {avg:>4}WPM,   last {last:>4}WPM"
    else:
        body = f"  need >= {need:>3}% Acc, avg. {avg:>3}% Acc, last {last:>3}% Acc"
    return "│" + body.ljust(77) + "│"


def render_keyboard(rows: list[str], show_ortho: bool, cat: bool) -> list[str]:
    if show_ortho:
        key_rows = [
            "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐",
            "│ " + " │ ".join(rows[0]) + " │",
            "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤",
            "│ " + " │ ".join(rows[1] + "△") + " │",
            "├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤",
            "│ " + " │ ".join(rows[2] + "△△") + " │",
            "└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘",
        ]
    else:
        row1 = "┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐"
        row2 = "│ " + " │ ".join(rows[0]) + " │"
        row3 = "└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘"
        row4 = " │ " + " │ ".join(rows[1]) + " │"
        row5 = " └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘"
        row6 = "  │ " + " │ ".join(rows[2]) + " │"
        row7 = "  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘"
        key_rows = [row1, row2, row3, row4, row5, row6, row7]
    left_pad = 5 if cat else (77 - len(key_rows[0])) // 2
    return ["│" + (" " * left_pad + row).ljust(77) + "│" for row in key_rows]


def overlay(base: str, text: str, column: int) -> str:
    if column >= len(base):
        return base
    chars = list(base)
    for index, ch in enumerate(text):
        pos = column + index
        if 0 <= pos < len(chars):
            chars[pos] = ch
    return "".join(chars)


def render_cat(lines: list[str], show_ortho: bool) -> list[str]:
    cat_art = {
        10: "          /\\_/\\\\",
        11: "         >(•༝• )<",
        12: "         |    \\",
        13: "         || |  )",
        14: "         ll-l-//",
        15: " /▔▔▔▔▔▔▔▔\\\\▔▔\\",
        16: "        \\__>",
    }
    for row, art in cat_art.items():
        if row < len(lines):
            lines[row] = overlay(lines[row], art, 52)
    return lines


def panic_screen(lines: list[str]) -> list[str]:
    if len(lines) > 7:
        lines[7] = "│" + PANIC_LINES[0].ljust(77)[:77] + "│"
    if len(lines) > 8:
        lines[8] = "│" + PANIC_LINES[1].ljust(77)[:77] + "│"
    if len(lines) > 9:
        lines[9] = "│" + PANIC_LINES[2].ljust(77)[:77] + "│"
    return lines


def build_mistake_overlay(state: GameState) -> str:
    if not state.lesson:
        return ""
    if not state.typed_actual:
        return ""
    chars = [" "] * len(state.lesson.visible)
    for position, value in state.typed_actual.items():
        if 0 <= position < len(chars):
            chars[position] = value
    return "".join(chars).rstrip()


def render_prompt(state: GameState) -> str:
    if not state.lesson:
        return ""
    visible = state.lesson.visible
    if state.cursor >= len(visible):
        return visible + "•"
    return visible


def render(state: GameState, panic: bool = False) -> str:
    lesson_number = state.lesson_count if state.lesson is not None else 0
    header = f"    Lesson #{lesson_number}"
    score = f"✔: {state.success_count}, ✘: {state.failure_count}    "
    line4 = "│" + header.ljust(77 - len(score)) + score + "│"
    lines = [
        border_top(),
        "│" + center_text("ngrrram!   by winterveil", 77) + "│",
        separator_line(),
        line4,
        separator_line(),
        blank_line(),
        "│" + center_text(render_prompt(state), 77) + "│",
        "│" + center_text(build_mistake_overlay(state), 77) + "│",
    ]
    if state.options.nokb:
        lines.extend([
            blank_line(),
            separator_line(),
            metric_line("WPM", state.options.wpm, state.avg_wpm, state.last_wpm),
            metric_line("ACC", state.options.acc, state.avg_acc, state.last_acc),
            border_bottom(),
        ])
    else:
        lines.append(blank_line())
        keyboard = render_keyboard(state.output_layout, state.options.show_ortho, state.options.cat)
        lines.extend(keyboard)
        lines.append(separator_line())
        lines.append(metric_line("WPM", state.options.wpm, state.avg_wpm, state.last_wpm))
        lines.append(metric_line("ACC", state.options.acc, state.avg_acc, state.last_acc))
        lines.append(border_bottom())
        if state.options.cat:
            lines = render_cat(lines, state.options.show_ortho)
    if panic:
        lines = panic_screen(lines)
    return "\x1b[H" + "\n".join(lines)


def complete_lesson(state: GameState) -> None:
    elapsed = max(time.monotonic() - (state.started_at or time.monotonic()), 0.001)
    nonspace = sum(1 for ch in state.lesson.expected if ch != " ")
    wpm = round(((nonspace / 5.0) * 60.0) / elapsed)
    acc = round((state.good_presses / max(state.total_presses, 1)) * 100)
    state.last_wpm = wpm
    state.last_acc = acc
    state.wpm_history.append(wpm)
    state.acc_history.append(acc)
    state.avg_wpm = round(sum(state.wpm_history) / len(state.wpm_history))
    state.avg_acc = round(sum(state.acc_history) / len(state.acc_history))
    if wpm >= state.options.wpm and acc >= state.options.acc:
        state.success_count += 1
    else:
        state.failure_count += 1
    state.lessons_done += 1
    state.reset_for_next_lesson()


def apply_input_char(state: GameState, raw_char: str, translate: dict[str, str]) -> None:
    if raw_char in ("\x08", "\x7f"):
        state.total_presses += 1
        current = state.mistakes.get(state.cursor)
        if current:
            current.pop()
            if current:
                state.typed_actual[state.cursor] = current[-1]
            else:
                state.mistakes.pop(state.cursor, None)
                state.typed_actual.pop(state.cursor, None)
            state.good_presses += 1
        return
    if not state.lesson or raw_char == "\x1b":
        return
    if len(raw_char) != 1 or ord(raw_char) < 32 or ord(raw_char) > 126:
        return
    mapped = translate.get(raw_char, raw_char)
    expected = state.lesson.expected[state.cursor] if state.cursor < len(state.lesson.expected) else ""
    if state.started_at is None:
        state.started_at = time.monotonic()
    state.total_presses += 1
    if mapped == expected:
        state.good_presses += 1
        if state.cursor < len(state.lesson.visible):
            state.typed_actual[state.cursor] = mapped
        state.cursor += 1
        if state.cursor >= len(state.lesson.expected):
            if not state.mistakes:
                complete_lesson(state)
            else:
                state.cursor = len(state.lesson.visible)
        return
    state.mistakes.setdefault(state.cursor, []).append(mapped)
    state.typed_actual[state.cursor] = mapped


def read_input(timeout: float = 0.05) -> str | None:
    ready, _, _ = select.select([sys.stdin], [], [], timeout)
    if not ready:
        return None
    data = os.read(sys.stdin.fileno(), 32)
    if not data:
        return "\x1b"
    return data.decode("utf-8", "ignore")


def run_game(opts: Options, pool: list[str]) -> int:
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        sys.stdout.write(TTY_ERROR + "\n")
        return 1
    output_layout = get_layout_rows(opts.emu_out or "qwerty")
    input_layout = get_layout_rows(opts.emu_in or "qwerty")
    translate = build_translation(input_layout, output_layout)
    state = GameState(
        options=opts,
        pool=pool[: max(1, min(opts.top, len(pool)))],
        output_layout=output_layout,
        input_layout=input_layout,
    )
    ui = TerminalUI()
    ui.enter()
    try:
        if not state.pool:
            sys.stdout.write(render(state, panic=True))
            sys.stdout.flush()
            return 101
        state.reset_for_next_lesson()
        sys.stdout.write(render(state))
        sys.stdout.flush()
        while not state.quitting:
            data = read_input()
            if data is None:
                continue
            for char in data:
                if char == "\x1b":
                    state.quitting = True
                    break
                apply_input_char(state, char, translate)
            sys.stdout.write(render(state))
            sys.stdout.flush()
        return 0
    finally:
        ui.leave()


def main() -> int:
    try:
        opts = parse_args(sys.argv[1:])
    except SystemExit as exc:
        return int(exc.code)
    validate_options(opts)
    pool = get_pool(opts)
    return run_game(opts, pool)


if __name__ == "__main__":
    raise SystemExit(main())

