import os, pty, select, time, fcntl, termios, struct
class Screen:
    def __init__(self, rows=40, cols=120): self.rows=rows; self.cols=cols; self.buf=[[' ']*cols for _ in range(rows)]; self.r=0; self.c=0
    def put(self,ch):
        if ch=='\n': self.r=min(self.rows-1,self.r+1); self.c=0; return
        if ch=='\r': self.c=0; return
        if ch=='\b': self.c=max(0,self.c-1); return
        if ord(ch)<32: return
        if 0<=self.r<self.rows and 0<=self.c<self.cols: self.buf[self.r][self.c]=ch
        self.c=min(self.cols-1,self.c+1)
    def csi(self,seq,final):
        if final in 'Hf':
            if seq.startswith('?'): return
            ps=[int(p) if p else 1 for p in seq.split(';')] if seq else [1]
            self.r=max(0,min(self.rows-1,ps[0]-1)); self.c=max(0,min(self.cols-1,(ps[1] if len(ps)>1 else 1)-1))
        elif final=='J':
            if (seq or '0').isdigit() and int(seq or '0')==2: self.buf=[[' ']*self.cols for _ in range(self.rows)]; self.r=self.c=0
    def feed(self,data):
        i=0
        while i<len(data):
            if data[i]=='\x1b' and i+1<len(data) and data[i+1]=='[':
                j=i+2
                while j<len(data) and not ('@'<=data[j]<='~'): j+=1
                if j<len(data): self.csi(data[i+2:j],data[j]); i=j+1; continue
                break
            if data[i]=='\x1b': i+=1; continue
            self.put(data[i]); i+=1
    def dump(self):
        lines=[''.join(r).rstrip() for r in self.buf]
        while lines and not lines[-1]: lines.pop()
        return '\n'.join(lines)

def run(cmd, inputs):
    master, slave=pty.openpty(); fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',24,80,0,0))
    pid=os.fork()
    if pid==0:
        os.setsid(); fcntl.ioctl(slave, termios.TIOCSCTTY,0); os.environ['TERM']='xterm-256color'; os.dup2(slave,0); os.dup2(slave,1); os.dup2(slave,2); os.close(master); os.close(slave); os.execv('/bin/bash',['bash','-lc',cmd])
    os.close(slave)
    s=Screen()
    def pump(sec):
        end=time.time()+sec
        while time.time()<end:
            r,_,_=select.select([master],[],[],0.05)
            if master in r:
                try:data=os.read(master,65536).decode('utf-8','replace')
                except OSError: break
                s.feed(data)
    pump(0.4)
    for chars, delay in inputs:
        os.write(master, chars)
        pump(delay)
    print(s.dump())
    try: os.write(master,b'\x1b')
    except OSError: pass
    pump(0.1)
    os.waitpid(pid,0)

open('/tmp/words.csv','w').write('foo,bar\n')
run('./executable -n /tmp/words.csv -t 1 -c 1 -r 1 --nokb', [(b'foo ',0.8)])
